#!/usr/bin/env bash
# Downloads Oakland 311 requests inside the Lake Merritt polygon to data/api/311.json.
# Writes to a temp file first, so a failed download never clobbers the existing data.
# If SOCRATA_APP_TOKEN is set (e.g. as a GitHub Actions secret), it's sent as an app
# token, which gives the request its own rate limit instead of the shared anonymous one.
set -euo pipefail
cd "$(dirname "$0")/.."

mkdir -p data/api # gitignored, so it doesn't exist in a fresh checkout
tmp="$(mktemp data/api/311.json.XXXXXX)"
trap 'rm -f "$tmp"' EXIT

token_header=()
if [[ -n "${SOCRATA_APP_TOKEN:-}" ]]; then
  token_header=(-H "X-App-Token: $SOCRATA_APP_TOKEN")
fi

# ${arr[@]+"${arr[@]}"} expands an empty array safely under `set -u` in older bash (macOS 3.2).
curl --fail-with-body --silent --show-error ${token_header[@]+"${token_header[@]}"} \
  --json '{
